  test("cancel statement scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "clerk-limit", "1.50");
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "proof-threshold", "3.00");
    await ui.setSetting(pg_uma, "perm-void", "clerk");
    await ui.setSetting(pg_uma, "grace-days", "0");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50", "from": "2026-03-16"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "99.95", "date": "2026-02-10"}));
    expect(await ui.editPerson(pg_uma, p_ben, {"grade": "A"})).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.reassign(pg_vic, c_cam_0, "Ben")).toBe(true);
    expect(await ui.retire(pg_vic, p_ada, "2026-03-15")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_cam_0, "open")).toBe(true);
    await ui.showRetired(pg_vic, true);
    expect(await ui.pasteClaims(pg_vic, "Ada,3.33,2026-03-09,a, b")).toBe(1);
    const c_ada_0 = await ui.claimAt(pg_vic, p_ada, 0);
    expect(await ui.editClaim(pg_vic, c_ada_0, {"amount": "12.50"})).toBe(true);
    await ui.refresh(pg_vic);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.claimAction(pg_wes, c_cam_0, "settle")).toBe(true);
    expect(await ui.pasteClaims(pg_wes, "Zed,1.00,2026-02-10,paste")).toBeNull();
    await ui.showRetired(pg_wes, true);
    expect(await ui.claimEditOpen(pg_wes, c_ada_0)).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimEditOpen(pg_vic, c_ada_0)).toBe(false);
    await ui.refresh(pg_wes);
    expect(await ui.claimEditSave(pg_wes, c_ada_0, {"amount": "0.40"})).toBe(true);
    expect(await ui.claimAction(pg_wes, c_ada_0, "void")).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.redate(pg_vic, c_cam_0, "2026-03-09")).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.watch(pg_wes, p_ben, true)).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.statement(pg_wes, p_ben)).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.unstate(pg_vic, p_ben)).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.redate(pg_vic, c_cam_0, "2026-03-09")).toBe(true);
    expect(await ui.addProof(pg_vic, c_cam_0)).toBe(true);
    expect(await ui.periodAction(pg_vic, "P1", "soft-close")).toBe(true);
    await ui.setToday(pg_vic, "2026-04-02");
    await ui.refresh(pg_vic);
    await ui.expectAudit(sheet, [
      `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=clerk-limit value=1.50`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=floor value=2.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=5.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=proof-threshold value=3.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=perm-void value=clerk`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=grace-days value=0`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=7.50 from=2026-03-16`,
      `PERIOD_ADDED sheet=${sheet} by=uma period=P1 from=2026-03-01 to=2026-03-15`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=C`,
      `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cam amount=99.95 date=2026-02-10`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Ben grade=A`,
      `CLAIM_REASSIGNED sheet=${sheet} by=vic person=Ben amount=99.95 date=2026-02-10 from=Cam to=Ben`,
      `PERSON_RETIRED sheet=${sheet} by=vic name=Ada from=2026-03-15`,
      `CLAIM_OPENED sheet=${sheet} by=vic person=Ben amount=99.95 date=2026-02-10 number=1`,
      `ROLLUP sheet=${sheet} by=vic person=Ben claimed=99.95 due-total=10.00 overdue-total=10.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=99.95 due-total=10.00 overdue-total=0.00`,
      `CLAIM_ADDED sheet=${sheet} by=vic person=Ada amount=3.33 date=2026-03-09`,
      `CLAIM_EDITED sheet=${sheet} by=vic person=Ada amount=12.50 date=2026-03-09`,
      `CLAIM_PENDING sheet=${sheet} by=wes person=Ben amount=99.95 date=2026-02-10 number=1`,
      `CLAIM_EDITED sheet=${sheet} by=wes person=Ada amount=0.40 date=2026-03-09`,
      `CLAIM_VOIDED sheet=${sheet} by=wes person=Ada amount=0.40 date=2026-03-09`,
      `CLAIM_REDATED sheet=${sheet} by=vic person=Ben amount=99.95 date=2026-03-09 number=1 old=2026-02-10 new=2026-03-09`,
      `PERSON_WATCHED sheet=${sheet} by=wes name=Ben`,
      `STATEMENT sheet=${sheet} by=wes name=Ben due-total=10.00 claims=1`,
      `STATEMENT_CANCELLED sheet=${sheet} by=vic name=Ben due-total=10.00`,
      `CLAIM_REDATED sheet=${sheet} by=vic person=Ben amount=99.95 date=2026-03-09 number=1 old=2026-03-09 new=2026-03-09`,
      `CLAIM_PROOF_ADDED sheet=${sheet} by=vic person=Ben amount=99.95 date=2026-03-09 number=1 proofs=1`,
      `PERIOD_SOFT_CLOSED sheet=${sheet} by=vic period=P1 total=10.00`,
      `ROLLUP sheet=${sheet} by=vic person=Ben claimed=99.95 due-total=10.50 overdue-total=10.50`,
      `TOTALS sheet=${sheet} by=vic claimed-total=99.95 due-total=10.50 overdue-total=0.00`
    ]);
  });
});
