package net.officefloor.hq.app.patron;

/** A patron that may not be named: not on the sheet, the person themselves, or already named. */
public class PatronRefusedException extends Exception {

    public PatronRefusedException(String message) {
        super(message);
    }
}
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { claimsKey } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { useUser } from '../session/useUser';
import { usePersonError } from '../people/usePersonError';
import { statementsKey, statementsQuery } from './statementsQuery';
import type { Statements } from './statementsQuery';

/**
 * A person's statements and the button that takes one: it records their due-total now and binds each of
 * their counting claims to its figure now, until their next statement.
 */
function PersonStatement({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const shown = (useQuery(statementsQuery(sheetId)).data ?? []).find((s) => s.personId === personId);
  const take = useMutation({
    mutationFn: () =>
      postJson<Statements>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`, {}, user),
    // The claims are re-read first, so the count moves on only once the bound figures show.
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) });
    },
    onError: () => setError('The statement could not be taken.'),
  });

  return (
    <td>
      <span data-testid="person-statement-count">{shown?.count ?? 0}</span>{' '}
      <span data-testid="person-stated-total">{shown?.dueTotal ?? ''}</span>{' '}
      <span data-testid="person-statement-date">{shown?.date ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          setError('');
          once(() => take.mutateAsync());
        }}
      >
        Statement
      </button>
    </td>
  );
}

/** Whether the person's last statement bound the claim to its figure. */
function ClaimStated({ claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-stated">{claim.stated ? 'yes' : 'no'}</td>;
}

export const contributions = [
  PersonHeaders.fill({ order: 17, Component: () => <th>Statements</th> }),
  PersonCells.fill({ order: 17, Component: PersonStatement }),
  ClaimCells.fill({ order: 15, Component: ClaimStated }),
];
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

/**
 * A person's statements: how many were taken, and the last one's due-total ("n/a" when it had none) and
 * date (yyyy-mm-dd), both null when none was taken. A person with no statement has no entry.
 */
export type Statements = { personId: number; count: number; dueTotal: string | null; date: string | null };

/** Under the sheet's key, so re-loading the sheet re-reads its statements. */
export const statementsKey = (sheetId: string) => [...sheetKey(sheetId), 'statements'] as const;

export const statementsQuery = (sheetId: string) => ({
  queryKey: statementsKey(sheetId),
  queryFn: () => getJson<Statements[]>(`/api/sheets/${encodeURIComponent(sheetId)}/statements`),
});
import { useSyncExternalStore } from 'react';

// One refusal per person row, shared by every cell that acts on the person (statement, retire, hold), so
// the row shows a single `person-error` and the next action on the row, whichever cell takes it, clears the last one.
const errors = new Map<number, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function setError(personId: number, error: string) {
  if ((errors.get(personId) ?? '') === error) return;
  if (error) errors.set(personId, error);
  else errors.delete(personId);
  listeners.forEach((l) => l());
}

/** The person's refusal ('' when none) and its setter. */
export function usePersonError(personId: number): [string, (error: string) => void] {
  const error = useSyncExternalStore(subscribe, () => errors.get(personId) ?? '');
  return [error, (next) => setError(personId, next)];
}

